data.codeBody:
q = question if isinstance(question, str) and question.strip() else prompt
if not isinstance(q, str) or not q.strip():
    raise ValueError("Ask a question.")
e = str(effort or "standard").strip().lower()
if e not in ("quick", "standard", "deep"):
    raise ValueError("Effort must be quick, standard or deep.")
return {"question_text": q.strip(), "effort_level": e}

arguments = {}
if query is not None and query != "":
    arguments["query"] = query
if since is not None and since != "":
    arguments["since"] = since
if until is not None and until != "":
    arguments["until"] = until
if entities is not None and entities != "":
    arguments["entities"] = entities
if topics is not None and topics != "":
    arguments["topics"] = topics
if limit is not None and limit != "":
    arguments["limit"] = limit
return {"tool_calls": [{"name": "note_search", "call_id": "search", "arguments": arguments}]}

r = results[0] if isinstance(results, list) and results else None
failure = None
out = None
if not isinstance(r, dict):
    failure = "note_search returned no result."
elif not r.get("success"):
    failure = str(r.get("error") or "note_search failed.")
else:
    out = r.get("output")
    if not isinstance(out, dict):
        failure = "note_search returned something other than an object."
if failure is not None:
    raise ValueError(failure)
return dict(out, tool_output=out)

found = [n for n in (notes or []) if isinstance(n, dict)]
evidence = [{"note_id": n.get("note_id"), "title": n.get("title"), "kind": n.get("kind"),
             "occurred_at": n.get("occurred_at"), "excerpt": n.get("excerpt")} for n in found]
if not found:
    text = "I found nothing in your notes about that."
else:
    items = ["\u201c" + str(n.get("title") or "Untitled") + "\u201d (" + str(n.get("occurred_at") or "")[:10] + ") [" + str(n.get("note_id")) + "]" for n in found[:5]]
    text = "I found " + str(len(found)) + (" note: " if len(found) == 1 else " notes: ") + "; ".join(items) + "."
return {"response": text, "answer": text, "evidence": evidence, "evolution": {}, "open_loops": [],
        "follow_ups": [], "dossier_note_id": None}

arguments = {}
if note_ids is not None and note_ids != "":
    arguments["note_ids"] = note_ids
if entity_ids is not None and entity_ids != "":
    arguments["entity_ids"] = entity_ids
if as_of is not None and as_of != "":
    arguments["as_of"] = as_of
return {"tool_calls": [{"name": "note_expand", "call_id": "expand", "arguments": arguments}]}

r = results[0] if isinstance(results, list) and results else None
failure = None
out = None
if not isinstance(r, dict):
    failure = "note_expand returned no result."
elif not r.get("success"):
    failure = str(r.get("error") or "note_expand failed.")
else:
    out = r.get("output")
    if not isinstance(out, dict):
        failure = "note_expand returned something other than an object."
if failure is not None:
    raise ValueError(failure)
return dict(out, tool_output=out)

pinDefaults.template:
You answer a question from a person's own notes.

Question: {{question}}
As of: {{as_of}}

Search results:
{{hits}}

Entity cards, claim timelines, relation timelines and then-versus-now pairs:
{{expansion}}

Write the `answer` with inline citations like [nt_...] using only the note ids above. Then give the `evidence` (note id, title, date, excerpt), what changed over time (`evolution`: the earliest stance, the latest stance, and the turning points with their note ids), the related `open_loops`, and up to three `follow_ups` worth asking next. When the notes do not answer the question, say so plainly in the answer.

Rules:
- Use only the material above; never invent notes, people or dates.
- Prefer the latest belief, and say when it changed and why.
- Output JSON only, matching the schema.

data.codeBody:
d = data if isinstance(data, dict) else {}
text = str(d.get("answer") or "").strip()
if not text:
    raise ValueError("The answer came back empty.")
found = {n.get("note_id"): n for n in (notes or []) if isinstance(n, dict) and n.get("note_id")}
evidence, seen = [], set()
for e in d.get("evidence") or []:
    n = found.get(e.get("note_id")) if isinstance(e, dict) else None
    if n is None or n["note_id"] in seen:
        continue
    seen.add(n["note_id"])
    evidence.append({"note_id": n["note_id"], "title": n.get("title"), "kind": n.get("kind"),
                     "occurred_at": n.get("occurred_at"), "excerpt": e.get("excerpt") or n.get("excerpt")})
return {"response": text, "answer": text, "evidence": evidence,
        "evolution": d.get("evolution") or {}, "open_loops": d.get("open_loops") or [],
        "follow_ups": d.get("follow_ups") or [], "dossier_note_id": None}

o = output if isinstance(output, dict) else {}
c = child_output if isinstance(child_output, dict) else {}
if c.get("success") is False or o.get("success") is False:
    err = str(c.get("error") or o.get("error") or "The step could not finish.")
    for prefix in ("Runtime error: ", "Execution error: "):
        if err.startswith(prefix):
            err = err[len(prefix):]
    raise ValueError(err)
return {"checked": True}
